def collect_labels(
    source: fitz.Document,
    content_pages: list[int],
    scale: float,
    questions: int,
    existing: dict[int, tuple[int, float, float]],
) -> dict[int, tuple[int, float, float]]:
    """Detect labels on each page, then assign in reading order with increasing numbers."""
    labels = dict(existing)
    page_hits: dict[int, list[tuple[int, float, float]]] = {}
    for page_index in content_pages:
        page_hits[page_index] = detect_labels(source[page_index], scale, questions)

    events: list[tuple[int, float, int, float]] = []
    for page_index in content_pages:
        for number, x, y in page_hits[page_index]:
            if number in labels:
                continue
            events.append((page_index, y, number, x))
    events.sort()

    # Walk top-to-bottom / page-by-page; only accept increasing question numbers.
    # Gaps (missed OCR) stay missing for --overrides; late false "1." cannot steal q1
    # after later questions have already been placed.
    last_number = max(labels.keys(), default=0)
    last_pos = (-1, -1.0)
    if labels:
        # Anchor the chain after the last override / existing label in reading order.
        ordered_existing = sorted(
            ((page, y, number) for number, (page, _x, y) in labels.items()),
            key=lambda item: (item[0], item[1], item[2]),
        )
        page, y, number = ordered_existing[-1]
        last_number = number
        last_pos = (page, y)

    for page_index, y, number, x in events:
        if number <= last_number or number in labels:
            continue
        if (page_index, y) <= last_pos:
            continue
        labels[number] = (page_index, x, y)
        last_number = number
        last_pos = (page_index, y)
    return labels


def enforce_label_order(
    labels: dict[int, tuple[int, float, float]],
    questions: int,
) -> dict[int, tuple[int, float, float]]:
    """Drop only individual labels that break increasing (page, y) order."""
    ordered: dict[int, tuple[int, float, float]] = {}
    previous: tuple[int, float] | None = None
    rejected: list[int] = []
    for number in range(1, questions + 1):
        if number not in labels:
            continue
        page_index, x, y = labels[number]
        key = (page_index, y)
        if previous is not None and key <= previous:
            rejected.append(number)
            continue
        ordered[number] = (page_index, x, y)
        previous = key
    if rejected:
        print(f"Rejected out-of-order labels: {rejected}")
    return ordered

