\begin{itemize}[leftmargin=1.4em]
  \item \textbf{Contact:} charge is shared when two conductors touch.
  \item \textbf{Induction:} a charged object brought near a conductor
        redistributes free charges in the conductor without touching it.
        If the conductor is then earthed, it can be left with a net charge
        opposite to the inducing charge.
\end{itemize}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Exam habit.}
For ``which spheres attract?'' questions, remember:
\begin{enumerate}[leftmargin=1.6em]
  \item Two objects with net charge of the \emph{same} sign always repel.
  \item Opposite signs always attract.
  \item A charged object and an \emph{uncharged} conductor attract
        (by induction). Two uncharged conductors do not attract electrostatically.
\end{enumerate}
\end{mdframed}

\mcquestion{2012}{24}{B}{86}{2012_q24.png}

\noindent\textbf{Solution sketch.}
$P$ and $Q$ repel $\Rightarrow$ same sign.
$R$ and $S$ repel $\Rightarrow$ same sign.
$Q$ and $R$ attract $\Rightarrow$ opposite signs.
So $\{P,Q\}$ is one sign and $\{R,S\}$ is the other.
\begin{itemize}[leftmargin=1.4em]
  \item (1) $P$ and $R$ both negative --- impossible (they must be opposite).
  \item (2) $Q$ and $S$ both positive --- impossible (they must be opposite).
  \item (3) $P$ positive and $S$ negative --- possible
        ($P,Q$ positive; $R,S$ negative).
\end{itemize}
Hence only (3) $\Rightarrow$ \textbf{B}.

\mcquestion{2015}{21}{B}{73}{2015_q21.png}

\noindent\textbf{Solution sketch.}
Any two balls attract. If two were charged with the \emph{same} sign they would
repel, so that pair cannot exist. The only consistent picture is:
\textbf{one uncharged} and the other two with \textbf{unlike} charges.
Then: unlike pair attracts; each charged ball attracts the neutral one by
induction. Option~A fails because like charges would repel.
$\Rightarrow$ \textbf{B}.

\section{Coulomb's law}

For two point charges $q_1$ and $q_2$ separated by distance $r$ in vacuum
(or air),
\[
F = \frac{1}{4\pi\varepsilon_0}\frac{|q_1 q_2|}{r^2}
  = k\frac{|q_1 q_2|}{r^2},
\qquad
k = 9.0\times 10^{9}\,\mathrm{N\,m^{2}\,C^{-2}}.
\]
\begin{itemize}[leftmargin=1.4em]
  \item Direction: along the line joining the charges; repulsive if same sign,
        attractive if opposite.
  \item Inverse-square law: if $r$ doubles, $F$ becomes $\tfrac14$.
  \item If both charges are scaled by a factor $n$ and the separation by $m$,
        then $F' = \dfrac{n^{2}}{m^{2}}F$.
\end{itemize}

\mcquestion{2026}{21}{B}{}{2026_q21.png}

\noindent\textbf{Solution sketch.}
\[
F' = k\frac{(2q_1)(2q_2)}{(2r)^{2}}
    = k\frac{4q_1 q_2}{4r^{2}} = F.
\]
So the force is unchanged $\Rightarrow$ \textbf{B}.

\section{Electric field}

\subsection{Definition}
The electric field $\vec E$ at a point is the force per unit positive charge:
\[
\vec E = \frac{\vec F}{q_0}
\quad\Rightarrow\quad
\vec F = q_0\vec E.
\]
Unit: $\mathrm{N\,C^{-1}}$ or $\mathrm{V\,m^{-1}}$.

\subsection{Field of a point charge}
\[
E = \frac{k|Q|}{r^{2}},
\]
directed \textbf{away from} a positive charge and \textbf{towards} a negative
charge.

\subsection{Superposition}
Fields add as vectors:
\[
\vec E_{\text{net}} = \vec E_1 + \vec E_2 + \cdots.
\]
On a straight line this reduces to careful signed addition.

\subsection{Where can $E=0$?}
For two charges on a line:
\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Charge types & Region where $E$ can vanish \\
\midrule
Same sign & Outside, nearer the \emph{smaller} $|Q|$ \\
Opposite signs & Outside, on the side of the \emph{smaller} $|Q|$ \\
 & (never between them: both fields point the same way) \\
\bottomrule
\end{tabular}
\end{center}
Set $k|Q_1|/r_1^{2} = k|Q_2|/r_2^{2}$ and solve $r_1/r_2 = \sqrt{|Q_1|/|Q_2|}$.

\mcquestion{2015}{22}{D}{33}{2015_q22.png}

\noindent\textbf{Solution sketch.}
Charges $-4Q$ and $+Q$ are opposite, so $E=0$ cannot lie between them.
It must be outside, on the side of the smaller charge $+Q$ (to the right).
Magnitudes equal when distance to $-4Q$ is twice the distance to $+Q$.
With 3~grid units between the charges, that point is 3~units right of $+Q$
$\Rightarrow$ \textbf{Z} $\Rightarrow$ \textbf{D}.

\mcquestion{2012}{25}{B}{49}{2012_q25.png}

\noindent\textbf{Solution sketch.}
\begin{enumerate}[leftmargin=1.5em]
  \item \textbf{Field zero:} opposite charges $\Rightarrow$ outside, beside
        smaller $|Q|$ which is $-Q$ $\Rightarrow$ point \textbf{Z}.
  \item \textbf{Potential zero:} $V$ is a scalar,
        $k(2Q)/r_{+} + k(-Q)/r_{-} = 0 \Rightarrow r_{+} = 2 r_{-}$.
        Between the charges this lies closer to $-Q$, i.e.\ point \textbf{Y}.
\end{enumerate}
So (1)~Z, (2)~Y $\Rightarrow$ \textbf{B}.

\subsection{Electric field lines}
\begin{itemize}[leftmargin=1.4em]
  \item Start on $+$ (or $\infty$), end on $-$ (or $\infty$).
  \item Density of lines $\propto$ field strength.
  \item Never cross; tangent gives direction of $\vec E$
        (force on a \emph{positive} test charge).
\end{itemize}

\mcquestion{2023}{24}{C}{62}{2023_q24.png}

\noindent\textbf{Solution sketch.}
Compare line density in regions $P$, $Q$, $R$: denser lines $\Rightarrow$
stronger $E$. Order the strengths accordingly (option~\textbf{C}).

\section{Electric potential and potential difference}

\subsection{Definitions}
Electric potential $V$ at a point is the work done by an external agent per
unit positive charge in bringing a test charge slowly from infinity to that
point (with $V(\infty)=0$):
\[
V = \frac{U}{q_0}.
\]
Unit: volt, $\mathrm{V} = \mathrm{J\,C^{-1}}$.

For a point charge,
\[
V = \frac{kQ}{r}
\]
(\textbf{signed}: positive near $+Q$, negative near $-Q$).

Potential is a \textbf{scalar}; potentials simply add:
\[
V_{\text{net}} = V_1 + V_2 + \cdots.
\]

Potential difference:
\[
\Delta V = V_A - V_B = -\int_A^B \vec E\cdot\mathrm{d}\vec\ell.
\]
In a uniform field of magnitude $E$, along a distance $d$ parallel to the
field,
\[
|\Delta V| = Ed.
\]

\begin{mdframed}[style=tipbox]
\noindent\textbf{Field vs potential --- don't mix them.}
\begin{itemize}[leftmargin=1.4em]
  \item $E=0$ does \emph{not} imply $V=0$ (and conversely).
  \item $E$ needs vector cancellation; $V$ needs signed scalar cancellation.
  \item A positive charge tends to move to lower $V$; a negative charge to
        higher $V$.
\end{itemize}
\end{mdframed}

\mcquestion{2014}{23}{B}{53}{2014_q23.png}

\noindent\textbf{Solution sketch.}
$V = kQ/r$. Point $X$ is 3~grid units from $+Q$ with $V_X = V$;
point $Y$ is 2~grid units away. Then
\[
V_Y = V\cdot\frac{r_X}{r_Y} = V\cdot\frac{3}{2} = \frac{3}{2}V
\Rightarrow \textbf{B}.
\]

\mcquestion{ppp}{25}{---}{}{ppp_q25.png}

\noindent\textbf{Solution sketch.}
In a \textbf{uniform} field, equipotentials are planes perpendicular to
$\vec E$, equally spaced for equal $\Delta V$.
Use $V_W$ and geometry of square $WXZY$ to find potentials at $X,Y,Z$.

\section{Uniform field between parallel plates}

Two large parallel plates with potential difference $V$ and separation $d$
produce an approximately uniform field
\[
E = \frac{V}{d}
\]
directed from the higher-potential (usually positive) plate to the lower.

Force on charge $q$: $F = qE = qV/d$.

\subsection{Millikan-style oil drop}
A droplet of mass $m$ and charge $q$ floats when electric force balances weight:
\[
qE = mg \quad\Rightarrow\quad q = \frac{mg}{E} = \frac{mgd}{V}.
\]
Polarity: for a \textbf{positive} drop to float, $\vec E$ (hence force) must be
\textbf{upward}.

\mcquestion{2018}{22}{A}{55}{2018_q22.png}

\noindent\textbf{Solution sketch.}
Floating $+Q$: electric force upward balances $mg$, so $\vec E$ is upward
(same direction as force on a positive charge). Strength:
$QE = mg \Rightarrow E = mg/Q$ $\Rightarrow$ \textbf{A}.

\mcquestion{2014}{22}{D}{61}{2014_q22.png}

\noindent\textbf{Solution sketch.}
Electron between plates: force is opposite to $\vec E$.
Read the marked force direction on the electron to deduce which plate is at
higher potential / how the battery is connected.

\section{Motion of charged particles in an electric field}

Neglect gravity unless the question is an oil-drop / floating problem.

\begin{itemize}[leftmargin=1.4em]
  \item Acceleration $\vec a = q\vec E / m$ (constant in a uniform field).
  \item If initial velocity is perpendicular to $\vec E$, the path is a
        \textbf{parabola} (same maths as projectile motion).
  \item Speed changes when the particle moves through a potential difference:
        $\tfrac12 mv^{2} = |q\,\Delta V|$ (energy conservation).
\end{itemize}

\mcquestion{2025}{23}{D}{63}{2025_q23.png}

\noindent\textbf{Solution sketch.}
Negative particle: force opposite to field lines.
With $\vec v$ perpendicular to $\vec E$, the trajectory curves toward the
direction of the force --- pick the diagram that matches.

\section{Multi-charge geometry (triangles, squares, lines)}

DSE loves three charges on a line, or charges at corners of a square /
equilateral triangle.
\begin{enumerate}[leftmargin=1.5em]
  \item Sketch each force (or field) as an arrow.
  \item Use symmetry: components perpendicular to a mirror line often cancel.
  \item Magnitudes from Coulomb / point-charge field formulae.
  \item For equilibrium of a middle charge on a line of three charges, net
        force on it is zero only for specific sign patterns
        (outer charges same sign and suitable sizes, etc.).
\end{enumerate}

\mcquestion{2015}{23}{A}{32}{2015_q23.png}

\noindent\textbf{Solution sketch.}
Field (or potential / force --- read the stem) at the third vertex of an
equilateral triangle with $+Q$ and $-Q$ at the other vertices.
The two contributions have equal magnitude $kQ/L^{2}$; resolve vectors at
$60^{\circ}$ to get the resultant.

\mcquestion{2025}{24}{A}{66}{2025_q24.png}

\noindent\textbf{Solution sketch.}
$+Q$ and $-Q$ at opposite corners of a square.
Use geometry ($r$, $\sqrt{2}\,r$) and vector addition / potential sum as asked.

\mcquestion{2019}{23}{A}{}{2019_q23.png}

\noindent\textbf{Solution sketch.}
Identical positive charges at the ends, movable charge in the middle:
analyse stability / direction of net force when the middle charge is displaced
along the line (or read the exact stem).

\section{Lightning and large-scale fields}

A nearly uniform field between cloud and ground:
breakdown when $E$ reaches a critical value
($\sim 3\times 10^{6}\,\mathrm{N\,C^{-1}}$ in air in DSE data).
Then $V = Ed$ over height $d$.

\mcquestion{2013}{25}{C}{58}{2013_q25.png}

\noindent\textbf{Solution sketch.}
Use $E = 3\times 10^{6}\,\mathrm{N\,C^{-1}}$ and the given height to find the
p.d.\ between cloud and ground (or the quantity asked).

\section{Formula sheet (electrostatics)}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Quantity & Formula \\
\midrule
Coulomb force & $F = k|q_1 q_2|/r^{2}$ \\
Point-charge field & $E = k|Q|/r^{2}$ \\
Point-charge potential & $V = kQ/r$ \\
Definition of field & $\vec E = \vec F/q$ \\
Uniform plates & $E = V/d$ \\
Floating drop & $qE = mg$ \\
Energy & $\Delta U = q\,\Delta V$ \\
\bottomrule
\end{tabular}
\end{center}

\clearpage
\section{Practice questions}

Attempt these without looking back. Answers (option + facility~\% when known)
are listed at the very end.

\mcpractice{2013}{24}{2013_q24.png}
\mcpractice{2014}{21}{2014_q21.png}
\mcpractice{2016}{24}{2016_q24.png}
\mcpractice{2017}{23}{2017_q23.png}
\mcpractice{2021}{22}{2021_q22.png}
