  % insulator
  \begin{scope}[shift={(4.2,0)}]
    \draw[thick] (0,0) circle (1.1);
    \foreach \a in {0,60,...,300} {
      \fill[gray!70] (\a:0.55) circle (1.4pt);
      \fill[negC!70] (\a:0.55)++(8:0.18) circle (1.2pt);
    }
    \node[font=\scriptsize,align=center] at (0,-1.45)
      {(b) Insulator: charges stay put\\(molecules may polarise)};
  \end{scope}
\end{tikzpicture}
\end{center}

\subsection{Charging methods (Active Physics)}
\begin{enumerate}[leftmargin=1.5em]
  \item \textbf{Friction (rubbing):} electrons transfer between materials.
  \item \textbf{Sharing (contact):} conductors touch; charge redistributes.
  \item \textbf{Induction:} a charged object nearby redistributes free charges
        \emph{without} contact. Momentary earthing can leave a net charge
        opposite to the inducer.
  \item \textbf{EHT supply:} high voltage source supplies charge.
\end{enumerate}
\textbf{Earthing:} sharing charge with the Earth (a huge conductor).

\subsection{Charged object attracting a neutral one}
A charged object does \textbf{not} attract a truly point-like neutral particle,
but it \emph{does} attract a neutral \textbf{conductor} (charge redistribution)
or \textbf{insulator} (polarisation of molecules).

