  }
  \node[below,font=\small] at (0,-1.85) {$+Q$: outwards};
  \begin{scope}[shift={(4.5,0)}]
    \node[circle,draw=negC,fill=negC!20,minimum size=7mm,font=\bfseries] at (0,0) {$-$};
    \foreach \a in {0,45,...,315} {
      \draw[-{Latex},thick,gray!70] (\a:1.55) -- (\a:0.55);
    }
    \node[below,font=\small] at (0,-1.85) {$-Q$: inwards};
  \end{scope}
\end{tikzpicture}
\end{center}

\subsection{Electric field lines}
\begin{itemize}[leftmargin=1.4em]
  \item Arrow: direction of $\vec E$ (force on $+q$).
  \item Line density $\propto$ magnitude of $E$.
  \item From $+$ to $-$ (or to/from infinity); never cross or branch.
\end{itemize}

\begin{center}
