\section{Electric potential and energy}

\subsection{Potential and potential difference}
Electric potential $V$ at a point: work per unit positive charge by an external
agent bringing a test charge slowly from infinity ($V(\infty)=0$):
\[
V = \frac{U}{q},\qquad [V]=\mathrm{V}=\mathrm{J\,C^{-1}}.
\]
For a point charge (signed!):
\[
V = k\frac{Q}{r}.
\]
Potentials are \textbf{scalars} and simply add.
In a uniform field, $|\Delta V| = Ed$ along the field direction.

\begin{center}
\begin{tikzpicture}[x=1.15cm,y=0.9cm]
  \draw[-{Latex},thick] (0,0) -- (5.2,0) node[right,font=\scriptsize] {$r$};
  \draw[-{Latex},thick] (0,0) -- (0,2.6) node[above,font=\scriptsize] {$V$};
  \draw[thick,domain=0.55:5,smooth,variable=\x,posC]
    plot ({\x},{2.0/\x});
  \draw[thick,domain=0.55:5,smooth,variable=\x,negC]
    plot ({\x},{-1.6/\x});
  \node[posC,font=\scriptsize] at (3.8,1.0) {$+Q$};
  \node[negC,font=\scriptsize] at (3.8,-0.85) {$-Q$};
  \node[below,font=\small] at (2.6,-1.5) {$V = kQ/r$ falls as $1/r$};
\end{tikzpicture}
\end{center}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Field vs potential.}
$E=0$ $\not\Rightarrow$ $V=0$ (and conversely).
$E$ needs vector cancellation; $V$ needs signed scalar cancellation.
$+$ charges tend to lower $V$; $-$ charges to higher $V$.
\end{mdframed}

\worked{2014}{23}{B}{53}{2014_q23.png}{%
$V\propto 1/r$. $X$ is 3~grid units from $+Q$ with $V_X=V$;
$Y$ is 2~units away $\Rightarrow$
$V_Y = V\cdot 3/2 = \tfrac32 V$ $\Rightarrow$ \textbf{B}.}

\worked{ppp}{25}{---}{}{ppp_q25.png}{%
$V_X=V_Y=5\,\mathrm{V}$ $\Rightarrow$ diagonal $XY$ equipotential.
Mid-point $M$ of the square also has $V_M=5\,\mathrm{V}$.
Along $WZ$, $V$ varies linearly:
$(V_W+V_Z)/2 = V_M \Rightarrow V_Z=9\,\mathrm{V}$ (option~\textbf{C}).}

\subsection{Work and electric potential energy}
Work to bring charge $q$ from infinity to a point at potential $V$:
\[
W_{\mathrm{ext}} = qV
\]
(use the \emph{net} $V$ from all fixed charges).
Energy released when charge $Q$ falls through p.d.\ $\Delta V$:
\[
W = Q\,\Delta V
\]
(e.g.\ estimate lightning energy with $\Delta V = Ed$).

\worked{2015}{23}{A}{32}{2015_q23.png}{%
At the empty vertex, $V = k(+Q)/L + k(-Q)/L = 0$.
Energy to bring another $+Q$ from infinity: $W=(+Q)V=0$ $\Rightarrow$ \textbf{A}.}

\worked{2013}{25}{C}{58}{2013_q25.png}{%
$\Delta V = Ed = (3\times 10^{6})(500)=1.5\times 10^{9}\,\mathrm{V}$.
$W = Q\Delta V = 20\times 1.5\times 10^{9} = 3\times 10^{10}\,\mathrm{J}$,
order $10^{10}\,\mathrm{J}$ $\Rightarrow$ \textbf{C}.}

