\section{Potential, e.m.f.\ and voltage}

\subsection{What does ``potential'' mean?}

\begin{center}
\begin{tabular}{@{}p{0.28\textwidth}p{0.66\textwidth}@{}}
\toprule
Term & Meaning in circuits \\
\midrule
Electric potential $V$
  & Energy per unit charge at a point, relative to an agreed zero
    (often the negative terminal / earth). Unit: volt (V).
    $1\,\mathrm{V}=1\,\mathrm{J\,C^{-1}}$. \\
Potential difference (p.d.)
  & Difference in potential between two points:
    energy converted per coulomb moving from one point to the other.
    $V=E/Q$. \\
e.m.f.\ $\mathcal{E}$
  & Energy \emph{gained} per coulomb inside a source. \\
Equipotential
  & Same potential: p.d.\ between those points is \textbf{zero}.
    Ideal connecting wires are treated as equipotential (negligible $R$). \\
\bottomrule
\end{tabular}
\end{center}

\begin{center}
\begin{tabular}{@{}p{0.46\textwidth}p{0.46\textwidth}@{}}
\toprule
\textbf{e.m.f.\ $\mathcal{E}$} & \textbf{p.d.\ $V$} \\
\midrule
Energy gained by 1~C in a source
&
Energy converted when 1~C moves between two points
\\[0.35em]
$\mathcal{E}=4\,\mathrm{V}$ $\Leftrightarrow$ 4~J gained per C in the battery
&
$V=1\,\mathrm{V}$ $\Leftrightarrow$ 1~J converted per C in a bulb
\\[0.35em]
\multicolumn{2}{l}{Ideal series loop: $\mathcal{E}=V_1+V_2+\cdots$ (energy gained $=$ energy spent).} \\
\bottomrule
\end{tabular}
\end{center}

\begin{center}
\begin{circuitikz}[scale=1.0, transform shape]
  \draw (0,0) to[battery1, l={$\mathcal{E}=4\,\mathrm{V}$}] (0,2.4)
        to[R, l={$R_1$}, a={p.d.\ $V_1=1\,\mathrm{V}$}] (3.0,2.4)
        to[R, l_={$R_2$}, a^={p.d.\ $V_2=3\,\mathrm{V}$}] (3.0,0)
        -- (0,0);
  \node[font=\scriptsize] at (1.5,-0.55) {series: $\mathcal{E}=V_1+V_2$};
\end{circuitikz}
\end{center}

\ex
Energy audit: $\mathcal{E}=4\,\mathrm{V}$, p.d.s $1\,\mathrm{V}$ and $3\,\mathrm{V}$ across two resistors.
If $6\,\mathrm{C}$ pass once around the loop, find the energy from the battery and the energy
converted in each resistor.
\sol[2.8cm]{%
Battery: $E=\mathcal{E}Q=4\times 6=24\,\mathrm{J}$.
First resistor: $1\times 6=6\,\mathrm{J}$. Second: $3\times 6=18\,\mathrm{J}$. Check: $6+18=24$.
}

\subsection{Short circuit and open circuit}

\begin{center}
\begin{tabular}{@{}p{0.22\textwidth}p{0.72\textwidth}@{}}
\toprule
Term & Meaning \\
\midrule
Short circuit
  & A path of (almost) zero resistance between two points. Those points become
    \textbf{equipotential}: p.d.\ across the short is $0$. Any component directly across the short
    is bypassed ($I$ prefers the short). Danger: huge current if a cell is shorted. \\
Open circuit
  & Break in the path ($R\to\infty$). No continuous route for charge $\Rightarrow$ $I=0$ in that branch. \\
Ideal wire
  & Modelled as $R=0$, so every point on the wire is at the same potential. \\
\bottomrule
\end{tabular}
\end{center}

\begin{center}
\begin{circuitikz}[scale=0.95, transform shape]
  % left: short across R2
  \draw (0,0) to[battery1, l=$12\,\mathrm{V}$] (0,2.2)
        to[R, l=$R_1$] (2.2,2.2)
        to[R, l_=$R_2$] (2.2,0) -- (0,0);
  \draw[thick,red!70!black] (1.85,2.2) -- (1.85,0);
  \node[font=\scriptsize,red!70!black] at (1.1,1.1) {short};
  \node[font=\scriptsize] at (1.1,-0.55) {$R_2$ bypassed; $V_{R_2}=0$};
  % right: open switch
  \begin{scope}[xshift=5.2cm]
    \draw (0,0) to[battery1] (0,2.2)
          to[R, l=$R$] (2.4,2.2)
          to[opening switch, l=open] (2.4,0) -- (0,0);
    \node[font=\scriptsize] at (1.2,-0.55) {open: $I=0$};
  \end{scope}
\end{circuitikz}
\end{center}

\conceptcheck{%
  True or false: the e.m.f.\ of a cell equals the p.d.\ across any one bulb in the same series loop.}
% answer: False (E = sum of p.d.s; not equal to one bulb alone unless only one load)

\ex
In the left diagram above, $R_1=R_2=6\,\Omega$ and the short is ideal. Find the current from the cell
and the p.d.\ across $R_1$.
\sol[3.2cm]{%
Short makes $V_{R_2}=0$, so $R_2$ carries no useful share: the load is only $R_1$.
$I=12/6=2.0\,\mathrm{A}$, $V_{R_1}=12\,\mathrm{V}$.
}

