%======================================================================
\section{Problem-solving skills}

\begin{center}
\begin{tabular}{@{}p{0.08\textwidth}p{0.86\textwidth}@{}}
\toprule
Step & What to do \\
\midrule
1 & Mark what is asked ($I$, $V$, $R_{\mathrm{eq}}$, $P$, \ldots) and what is given. \\
2 & Redraw: combine series / parallel; remove components across an ideal short. \\
3 & Label equipotential points (same letter if joined by ideal wire / short). \\
4 & Write $R_{\mathrm{eq}}$, then $I=\mathcal{E}/R_{\mathrm{eq}}$ (include $r$ if given). \\
5 & Split currents / voltages with series and parallel rules; check units. \\
6 & Sanity check: series $R_{\mathrm{eq}}>$ each part; parallel $R_{\mathrm{eq}}<$ smallest branch. \\
\bottomrule
\end{tabular}
\end{center}

\subsection{Skill: equipotential points}

\ex
Points joined by ideal wires are equipotential. In the network, $A$ is shorted to $C$ by an ideal wire.
\begin{center}
\begin{circuitikz}[scale=1.0, transform shape]
  \draw (0,0) node[ocirc]{} node[left,font=\scriptsize] {$P$}
        to[R, l=$2R$] (0,2)
        to[R, l=$R$] (2.5,2)
        to[R, l=$2R$] (2.5,0)
        to[R, l_=$R$] (0,0);
  \draw (0,2) node[circled,inner sep=1pt,font=\scriptsize] {$A$}
        to[short, red!70!black] (2.5,0) node[circled,inner sep=1pt,font=\scriptsize] {$C$};
  \draw (2.5,2) node[circled,inner sep=1pt,font=\scriptsize] {$B$};
  \draw (0,0) node[circled,inner sep=1pt,font=\scriptsize] {$D$};
  \draw (2.5,0) -- (3.2,0) node[ocirc]{} node[right,font=\scriptsize] {$Q$};
\end{circuitikz}
\end{center}
Which resistors are effectively in parallel between $P$ and $Q$? Find $R_{PQ}$ in terms of $R$.
\sol[4.2cm]{%
Short $A$--$C$: $A$ and $C$ are equipotential.
Then $R$ (top) is parallel with $2R$ (right), and $2R$ (left) is parallel with $R$ (bottom).
$R\parallel 2R=\tfrac{2}{3}R$ (twice).
These two combinations are in series: $R_{PQ}=\tfrac{2}{3}R+\tfrac{2}{3}R=\tfrac{4}{3}R$.
(If the diagram topology is read as a bridge shorted across one diagonal, redraw carefully;
the key skill is: short $\Rightarrow$ merge nodes, then regroup.)
}

\subsection{Skill: what a short does to a voltage divider}

\ex
\begin{center}
\begin{circuitikz}[scale=1.05, transform shape]
  \draw (0,0) to[battery1, l=$12\,\mathrm{V}$] (0,3.0)
        to[R, l=$3\,\Omega$] (0,1.5)
        to[R, l_=$6\,\Omega$] (0,0);
  \draw (0,1.5) -- (1.6,1.5) to[R, l=$6\,\Omega$] (1.6,0) -- (0,0);
  \draw[thick,red!70!black] (0,1.5) -- (-0.7,1.5) -- (-0.7,0) -- (0,0);
  \node[font=\scriptsize,red!70!black] at (-1.15,0.75) {short};
\end{circuitikz}
\end{center}
With the short connected as shown, find the current from the cell.
\sol[3.8cm]{%
Short joins the mid-node to the bottom rail $\Rightarrow$ both $6\,\Omega$ resistors are shorted out
($V=0$ across each). Only the $3\,\Omega$ remains.
$I=12/3=4.0\,\mathrm{A}$.
}

\subsection{Skill: combine, then split}

\ex
Two $4\,\Omega$ resistors in parallel are placed in series with a $2\,\Omega$ resistor across a $9\,\mathrm{V}$
ideal cell. Find (a)~$R_{\mathrm{eq}}$, (b)~the cell current, (c)~the current in one $4\,\Omega$ branch,
(d)~the power in the $2\,\Omega$ resistor.
\sol[4.5cm]{%
(a) $R_{\parallel}=4/2=2\,\Omega$, $R_{\mathrm{eq}}=2+2=4\,\Omega$.
(b) $I=9/4=2.25\,\mathrm{A}$.
(c) Equal parallel pair: each branch $I/2=1.125\,\mathrm{A}$.
(d) $P=I^{2}R=(2.25)^{2}(2)=10.1\,\mathrm{W}$.
}

%======================================================================
\section{Summary formulae}

\subsection{Skill: equipotential points}

\ex
Ideal wires are equipotential. In the figure, an ideal short joins $X$ to $Y$.
\begin{center}
\begin{circuitikz}[scale=1.05, transform shape]
  \draw (0,0) to[battery1, l=$12\,\mathrm{V}$] (0,2.4)
        to[R, l=$4\,\Omega$] (2.5,2.4)
        to[R, l=$4\,\Omega$] (5.0,2.4)
        -- (5.0,0) -- (0,0);
  \draw (2.5,2.4) node[circled,inner sep=1pt,font=\scriptsize] {$X$}
        to[R, l_=$8\,\Omega$] (2.5,0)
        node[circled,inner sep=1pt,font=\scriptsize] {$Y$};
  \draw[thick,red!70!black] (2.5,2.4) -- (3.3,2.4) -- (3.3,0) -- (2.5,0);
  \node[font=\scriptsize,red!70!black] at (3.85,1.2) {short};
\end{circuitikz}
\end{center}
Find the current from the cell after the short is connected.
\sol[3.8cm]{%
Short $\Rightarrow$ $X$ and $Y$ equipotential $\Rightarrow$ $V_{8\,\Omega}=0$, so the $8\,\Omega$ is bypassed.
Also the right-hand $4\,\Omega$ has both ends at the same potential as the bottom rail through the
short path\ldots cleaner redraw: short forces the mid-node to the bottom rail potential, so both
the lower $8\,\Omega$ and the right $4\,\Omega$ are shorted. Only the left $4\,\Omega$ remains.
$I=12/4=3.0\,\mathrm{A}$.
}

