\ex
\begin{enumerate}
  \item A lamp draws $I=2.0\,\mathrm{A}$ for $t=3.0$ minutes. How much charge passes?
  \item If $1.88\times 10^{18}$ electrons flow through a wire each second, what is the current?
        (Take $e=1.6\times 10^{-19}\,\mathrm{C}$.)
\end{enumerate}
\sol[3.0cm]{%
\begin{enumerate}
  \item $Q=It=2.0\times(3.0\times 60)=360\,\mathrm{C}$.
  \item $I=Ne=(1.88\times 10^{18})(1.6\times 10^{-19})=0.301\,\mathrm{A}$.
\end{enumerate}
}

\begin{enumerate}
  \item Energy from the battery?
  \item Energy converted in each resistor?
\end{enumerate}
\sol[2.8cm]{%
\begin{enumerate}
  \item Battery: $E=\mathcal{E}Q=4\times 6=24\,\mathrm{J}$.
  \item $R_1$: $1\times 6=6\,\mathrm{J}$. $R_2$: $3\times 6=18\,\mathrm{J}$. Check: $6+18=24$.
\end{enumerate}
}

\ex
Two $4\,\Omega$ in parallel, then series with $2\,\Omega$, across $9\,\mathrm{V}$ ideal.
\begin{enumerate}
  \item Find $R_{\mathrm{eq}}$.
  \item Find the cell current.
  \item Find the current in one $4\,\Omega$.
  \item Find the power in the $2\,\Omega$.
\end{enumerate}
\sol[3.5cm]{%
\begin{enumerate}
  \item $R_{\parallel}=2\,\Omega$, $R_{\mathrm{eq}}=4\,\Omega$.
  \item $I=9/4=2.25\,\mathrm{A}$.
  \item Equal parallel pair: each $1.125\,\mathrm{A}$.
  \item $P_{2}=I^{2}R=(2.25)^{2}(2)=10.1\,\mathrm{W}$.
\end{enumerate}
}

\ex
A $12\,\mathrm{V}$ battery of negligible internal resistance supplies $2.0\,\mathrm{A}$ to a heater for
$5.0$~minutes.
\begin{enumerate}
  \item Find the power.
  \item Find the energy transferred.
\end{enumerate}
\sol[3.8cm]{%
\begin{enumerate}
  \item $P=VI=(12)(2.0)=24\,\mathrm{W}$.
  \item $E=Pt=24\times(5.0\times 60)=7200\,\mathrm{J}$.
\end{enumerate}
}

