  \fill (2.2,0) circle (2pt) node[above left,font=\scriptsize] {$Q$};
  \draw[thick] (2.2,0) -- (4.0,0.9);
  \draw[thick] (2.2,0) -- (4.0,-0.9);
  \draw[-{Latex},thick,blue!60!black] (2.6,0.25) -- (3.7,0.75)
    node[midway,above,font=\scriptsize] {$5\,\mathrm{A}$};
  \draw[-{Latex},thick,blue!60!black] (2.6,-0.25) -- (3.7,-0.75)
    node[midway,below,font=\scriptsize] {$3\,\mathrm{A}$};
\end{tikzpicture}
\end{center}
  \item
\begin{center}
\begin{tikzpicture}[scale=1.15]
  \draw[thick] (2.0,0) -- (2.0,2.4);
  \fill (2.0,1.2) circle (2pt) node[below right,font=\scriptsize] {$Q$};
  \draw[thick] (0.2,2.4) -- (2.0,2.4);
  \draw[thick] (0.2,1.2) -- (2.0,1.2);
  \draw[thick] (0.2,0) -- (2.0,0);
  \draw[thick] (2.0,1.2) -- (4.0,1.2);
  \node[font=\scriptsize] at (0.9,1.0) {$P$};
