  \draw[-{Latex},thick,blue!60!black] (1.6,0) -- (0.4,0)
    node[midway,below,font=\scriptsize] {$3\,\mathrm{A}$};
  \draw[-{Latex},thick,blue!60!black] (2.4,1.2) -- (3.7,1.2)
    node[midway,above,font=\scriptsize] {$4\,\mathrm{A}$};
\end{tikzpicture}
\end{center}
\end{enumerate}
\sol[3.5cm]{%
\begin{enumerate}
  \item Out of $Q$: $5+3=8\,\mathrm{A}$. So $I_{PQ}=8\,\mathrm{A}$ from $P$ to $Q$.
  \item Treat the vertical as one node. Into node: $2\,\mathrm{A}+I_{PQ}$.
