    -- (5.6,-0.15) -- (0,-0.15) -- cycle;
  \draw[green!45!black, line width=1.2pt]
    (0.8,0) -- (0.8,2.2) -- (2.4,2.2) -- (3.6,1.2) -- (5.0,0);
  % climber / roller labels
  \draw[-{Latex},blue!60!black] (0.55,0.3) -- (0.55,1.9);
  \node[blue!60!black, left, align=right] at (0.4,1.1)
    {lift\\(gain energy)};
  \draw[-{Latex},orange!75!black] (2.7,2.0) -- (3.4,1.35);
  \draw[-{Latex},orange!75!black] (3.9,1.05) -- (4.7,0.25);
