\subsubsection*{Voltage $=$ energy per coulomb}

\begin{itemize}[leftmargin=1.2em,itemsep=0.12em,topsep=0.25em]
  \item \textbf{Potential} at a point: electrical energy per unit positive charge at that point
        (needs a chosen zero).
  \item \textbf{Potential difference} (p.d.\ / voltage) between two points: energy transferred
        per unit charge moving between them:
        \[
        V=\frac{W}{Q},\qquad 1\,\mathrm{V}=1\,\mathrm{J\,C^{-1}}.
        \]
  \item \textbf{e.m.f.}\ $\mathcal{E}$: energy \emph{supplied by a source} per unit charge:
        \[
        \mathcal{E}=\frac{W_{\mathrm{supplied}}}{Q}.
        \]
\end{itemize}

