def collapse_empty_bands(image: Image.Image, min_height: int = 40) -> Image.Image:
    """Remove tall blank bands left after wiping answer lines (keep a small spacer)."""
    gray = image.convert("L")
    w, h = gray.size
    pix = gray.load()

    def row_ink(y: int) -> int:
        ink = 0
        for x in range(0, w, 2):
            if pix[x, y] < 225:
                ink += 1
        return ink

    threshold = max(6, w // 60)
    keep_ranges: list[tuple[int, int]] = []
    y = 0
    while y < h:
        if row_ink(y) > threshold:
            y0 = y
            while y < h and row_ink(y) > threshold:
                y += 1
            keep_ranges.append((y0, y))
        else:
            y0 = y
            while y < h and row_ink(y) <= threshold:
                y += 1
            blank_h = y - y0
            if blank_h < min_height:
                # small gap — keep it
                keep_ranges.append((y0, y))
            else:
                # large answer gap — keep a thin spacer
                keep_ranges.append((y0, min(y0 + 8, y)))

    if not keep_ranges:
        return image
    merged: list[tuple[int, int]] = []
    for a, b in keep_ranges:
        if b <= a:
            continue
        if merged and a <= merged[-1][1] + 1:
            merged[-1] = (merged[-1][0], max(merged[-1][1], b))
        else:
            merged.append((a, b))
    total_h = sum(b - a for a, b in merged)
    # Safety: never drop below half the original content height.
    if total_h < h * 0.35:
        return image
    out = Image.new("RGB", (w, total_h), (255, 255, 255))
    y_out = 0
    for a, b in merged:
        out.paste(image.crop((0, a, w, b)), (0, y_out))
        y_out += b - a
    return out

