        image = render_page(page, scale, clip=clip)
        # Upscale strip for OCR.
        image = image.resize((image.width * 2, image.height * 2))
        rows = ocr_tsv(image)
        for row in rows:
            if row["conf"] < 20:
                continue
            text = row["text"].strip()
            text = text.replace("O", "0") if text in {"O", "O."} else text
            match = QNUM_RE.fullmatch(text) or re.fullmatch(r"[#*]?\s*(\d{1,2})[.,]?", text)
            if not match:
                continue
            qn = int(match.group(1))
            if qn < 1 or qn > max_questions:
                continue
            # row tops are in upscaled clip pixels
            y_pdf = TOP + (row["top"] / 2.0) / scale
            candidates.append((qn, page_index, y_pdf, row["conf"]))

    if not candidates:
        return []

    # Prefer highest-confidence hit per (qn), earliest page/y on ties.
    best: dict[int, tuple[int, float, float]] = {}
    for qn, page_index, y_pdf, conf in candidates:
        prev = best.get(qn)
        if prev is None or conf > prev[2] or (conf == prev[2] and (page_index, y_pdf) < (prev[0], prev[1])):
            best[qn] = (page_index, y_pdf, conf)

    ordered = sorted(((qn, *best[qn][:2]) for qn in best), key=lambda t: (t[1], t[2]))
    # Build increasing sequence starting at 1.
    cleaned: list[tuple[int, int, float]] = []
    expect = 1
    for qn, page_index, y_pdf in ordered:
        if qn == expect:
            cleaned.append((qn, page_index, y_pdf))
            expect += 1
        elif qn < expect:
            continue
        else:
            # Gap - stop (avoid false large numbers).
            break
    return cleaned

