def derotated_document(source: Path) -> fitz.Document:
    """Return a new PDF with page rotation baked into upright pages."""
    src = fitz.open(source)
    if all(page.rotation == 0 for page in src):
        return src
    out = fitz.open()
    for page in src:
        rot = page.rotation
        rect = page.rect
        if rot in (90, 270):
            width, height = rect.height, rect.width
        else:
            width, height = rect.width, rect.height
        new_page = out.new_page(width=width, height=height)
        new_page.show_pdf_page(new_page.rect, src, page.number, rotate=-rot)
    src.close()
    return out


def process_one(
    source: Path,
    output_dir: Path,
    cover_pages: int,
    scale: float,
    detect_scale: float,
    max_questions: int,
) -> int:
    doc = derotated_document(source)
    try:
        starts = find_question_starts_text(doc, cover_pages)
        if len(starts) < 5:
            ocr_starts = find_question_starts_ocr(doc, cover_pages, detect_scale, max_questions)
            if len(ocr_starts) > len(starts):
                starts = ocr_starts
        if not starts:
            print(f"  WARNING: no questions detected in {source.name}")
            return 0
        print(f"  detected Q{starts[0][0]}-Q{starts[-1][0]} ({len(starts)} questions)")
        images = crop_question_images(doc, starts, scale)
        output_dir.mkdir(parents=True, exist_ok=True)
        for qn, image in sorted(images.items()):
            image.save(output_dir / f"q{qn}.png", format="PNG", optimize=True)
        return len(images)
    finally:
        doc.close()

